using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "MyService",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["featureFlags"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaFeatures"] = false,
        },
    };

    /// <summary>Returns the full application configuration as JSON.</summary>
    [McpServerResource(UriTemplate = "config://app", Name = "app-config", MimeType = "application/json")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>Returns a specific configuration section by key.</summary>
    [McpServerResource(UriTemplate = "config://app/{section}", Name = "app-config-section", MimeType = "application/json")]
    public static string GetConfigSection(string section)
    {
        if (AppConfig.TryGetValue(section, out var value))
        {
            return JsonSerializer.Serialize(value, new JsonSerializerOptions { WriteIndented = true });
        }

        return JsonSerializer.Serialize(new { error = $"Section '{section}' not found" });
    }
}

